//! libjanus: the C ABI of the janus client SDK.
//!
//! The application links this library, starts a client inside its own process and mounts the
//! local SMB endpoint (loopback only) like any SMB share. See `README.md` for the embedding
//! logic and `janus/janus.h` for the declarations (generated by cbindgen from this file at build
//! time: `cargo run -p janus-ffi --example gen_header -- <out.h>`).
//!
//! Rules every exported function follows:
//! - a panic never crosses the boundary (`catch_unwind` → `JANUS_E_INTERNAL`);
//! - null pointers and invalid UTF-8 are errors, not undefined behaviour;
//! - the details of the last failure on the calling thread are available from
//!   [`janus_last_error`];
//! - calls are safe from any thread, except [`janus_client_stop`] from inside the log callback
//!   (refused with `JANUS_E_CALLBACK_CONTEXT`, the handle stays valid);
//! - secrets are never logged.

#![allow(non_camel_case_types)]

use std::cell::{Cell, RefCell};
use std::collections::VecDeque;
use std::ffi::{CStr, CString, c_char, c_int, c_uint, c_void};
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::path::PathBuf;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Condvar, Mutex};
use std::time::Duration;

use ::janus_client::{Client, ClientConfig, ClientError, Line, Sink, StopMode};
use janus_lib::config::ShareConfig;
use serde::Deserialize;

/// Version of this C ABI. Bumped on any incompatible change to the header.
pub const JANUS_ABI_VERSION: c_int = 1;

pub const JANUS_OK: c_int = 0;
/// A null pointer, invalid UTF-8, or an argument out of range.
pub const JANUS_E_INVALID_ARG: c_int = -1;
/// The configuration JSON is malformed or unusable.
pub const JANUS_E_INVALID_CONFIG: c_int = -2;
/// A client is already running in this process (one client per process).
pub const JANUS_E_ALREADY_STARTED: c_int = -3;
/// A listener could not be bound (port busy, no permission).
pub const JANUS_E_BIND: c_int = -4;
/// The receiver is not configured or not reachable over mTLS yet.
pub const JANUS_E_NOT_READY: c_int = -5;
/// The journal did not drain in time.
pub const JANUS_E_TIMEOUT: c_int = -6;
/// A bug or an unexpected failure inside the library (including a caught panic).
pub const JANUS_E_INTERNAL: c_int = -7;
/// `janus_client_stop` was called from inside the log callback.
pub const JANUS_E_CALLBACK_CONTEXT: c_int = -8;
/// The configuration is valid but could not be put in place (disk, journal, backend).
pub const JANUS_E_REFUSED: c_int = -9;
/// The journal could not be started.
pub const JANUS_E_JOURNAL: c_int = -10;

pub const JANUS_LOG_DEBUG: c_int = 0;
pub const JANUS_LOG_INFO: c_int = 1;
pub const JANUS_LOG_WARN: c_int = 2;
pub const JANUS_LOG_ERROR: c_int = 3;

/// Log callback. Called from a library thread, one line at a time, in order. `component` and
/// `message` are valid only during the call. It must return quickly and must not call
/// `janus_client_stop`. (Declared `C-unwind` so a Rust callback that panics is caught by the
/// library instead of aborting the process.) If it is slow the oldest lines are dropped (`log_dropped` in the
/// status JSON counts them).
pub type janus_log_fn = Option<
    unsafe extern "C-unwind" fn(
        level: c_int,
        component: *const c_char,
        message: *const c_char,
        user: *mut c_void,
    ),
>;

/// Lines buffered for a slow log callback before the oldest are dropped.
const LOG_QUEUE_CAP: usize = 1024;

/// Opaque handle of a running client.
pub struct janus_client {
    client: Client,
    pump: Option<Arc<LogPump>>,
}

// ---------------------------------------------------------------- errors

struct FfiError {
    code: c_int,
    msg: String,
}

fn err(code: c_int, msg: impl Into<String>) -> FfiError {
    FfiError {
        code,
        msg: msg.into(),
    }
}

impl From<ClientError> for FfiError {
    fn from(e: ClientError) -> FfiError {
        let code = match &e {
            ClientError::AlreadyStarted => JANUS_E_ALREADY_STARTED,
            ClientError::InvalidConfig(_) => JANUS_E_INVALID_CONFIG,
            ClientError::Bind(_) => JANUS_E_BIND,
            ClientError::NotReady(_) => JANUS_E_NOT_READY,
            ClientError::Timeout { .. } => JANUS_E_TIMEOUT,
            ClientError::Journal(_) => JANUS_E_JOURNAL,
            ClientError::Refused(_) => JANUS_E_REFUSED,
            ClientError::Internal(_) => JANUS_E_INTERNAL,
        };
        err(code, e.to_string())
    }
}

thread_local! {
    static LAST_ERROR: RefCell<String> = const { RefCell::new(String::new()) };
    /// Set on the thread that runs the log callback.
    static IN_CALLBACK: Cell<bool> = const { Cell::new(false) };
}

fn set_last_error(msg: &str) {
    LAST_ERROR.with(|e| *e.borrow_mut() = msg.to_owned());
}

/// Run `f`, turning errors and panics into return codes. Success clears the last error.
fn ffi(f: impl FnOnce() -> Result<(), FfiError>) -> c_int {
    match catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(())) => {
            set_last_error("");
            JANUS_OK
        }
        Ok(Err(e)) => {
            set_last_error(&e.msg);
            e.code
        }
        Err(p) => {
            let what = p
                .downcast_ref::<&str>()
                .map(|s| (*s).to_owned())
                .or_else(|| p.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "panic".into());
            set_last_error(&format!("internal error: {what}"));
            JANUS_E_INTERNAL
        }
    }
}

unsafe fn str_arg<'a>(p: *const c_char, name: &str) -> Result<&'a str, FfiError> {
    if p.is_null() {
        return Err(err(JANUS_E_INVALID_ARG, format!("{name} is null")));
    }
    // SAFETY: the caller promises a NUL-terminated string.
    unsafe { CStr::from_ptr(p) }
        .to_str()
        .map_err(|_| err(JANUS_E_INVALID_ARG, format!("{name} is not valid UTF-8")))
}

unsafe fn handle<'a>(c: *mut janus_client) -> Result<&'a janus_client, FfiError> {
    // SAFETY: the caller promises a pointer from `janus_client_start` that was not stopped.
    unsafe { c.as_ref() }.ok_or_else(|| err(JANUS_E_INVALID_ARG, "client handle is null"))
}

fn out_string(out: *mut *mut c_char, s: String) -> Result<(), FfiError> {
    if out.is_null() {
        return Err(err(JANUS_E_INVALID_ARG, "output pointer is null"));
    }
    let c = CString::new(s.replace('\0', " ")).map_err(|e| err(JANUS_E_INTERNAL, e.to_string()))?;
    // SAFETY: `out` was checked; the caller owns the string and frees it with janus_free_string.
    unsafe { *out = c.into_raw() };
    Ok(())
}

// ---------------------------------------------------------------- configuration

/// What the application passes to `janus_client_start`: the `ConfigStore` schema plus the
/// `client` section for this process.
#[derive(Deserialize, Default)]
#[serde(default)]
struct StartConfig {
    share: Option<ShareConfig>,
    client: ClientSection,
}

#[derive(Deserialize, Default)]
#[serde(default)]
struct ClientSection {
    /// Default `127.0.0.1:0` (a free port; read the result from `mount_info`).
    smb_listen: Option<String>,
    state_dir: Option<PathBuf>,
    smb_user: Option<String>,
    smb_password: Option<String>,
    smb_credentials_file: Option<PathBuf>,
    bonjour: bool,
    trace: u8,
    /// Off by default.
    control_listen: Option<String>,
    /// Development: serve this directory instead of the receiver.
    local_root: Option<PathBuf>,
    /// 0 = the default (2).
    worker_threads: usize,
    /// Print log lines to stderr. Default: only when no log callback is given.
    log_stderr: Option<bool>,
}

fn parse_config(json: &str, sink: Option<Sink>, has_cb: bool) -> Result<ClientConfig, FfiError> {
    let parsed: StartConfig = serde_json::from_str(json)
        .map_err(|e| err(JANUS_E_INVALID_CONFIG, format!("config JSON: {e}")))?;
    let c = parsed.client;
    let mut cfg = ClientConfig {
        share: parsed.share,
        state_dir: c.state_dir,
        smb_user: c.smb_user,
        smb_password: c.smb_password,
        smb_credentials_file: c.smb_credentials_file,
        control_listen: c.control_listen,
        local_root: c.local_root,
        bonjour: c.bonjour,
        trace: c.trace,
        log_sink: sink,
        log_stderr: c.log_stderr.unwrap_or(!has_cb),
        ..ClientConfig::default()
    };
    if let Some(a) = c.smb_listen {
        cfg.smb_listen = a;
    }
    if c.worker_threads > 0 {
        cfg.worker_threads = c.worker_threads;
    }
    Ok(cfg)
}

// ---------------------------------------------------------------- log pump

struct SendPtr(*mut c_void);
// SAFETY: the application promises that `user` may be used from the callback thread.
unsafe impl Send for SendPtr {}

struct Queue {
    lines: VecDeque<(c_int, String, String)>,
    closed: bool,
}

/// Decouples the client from the application's callback: a bounded queue and one thread.
struct LogPump {
    queue: Mutex<Queue>,
    cv: Condvar,
    dropped: AtomicU64,
    thread: Mutex<Option<std::thread::JoinHandle<()>>>,
}

impl LogPump {
    fn start(
        cb: unsafe extern "C-unwind" fn(c_int, *const c_char, *const c_char, *mut c_void),
        user: *mut c_void,
    ) -> Arc<LogPump> {
        let pump = Arc::new(LogPump {
            queue: Mutex::new(Queue {
                lines: VecDeque::new(),
                closed: false,
            }),
            cv: Condvar::new(),
            dropped: AtomicU64::new(0),
            thread: Mutex::new(None),
        });
        let user = SendPtr(user);
        let p = Arc::clone(&pump);
        let handle = std::thread::Builder::new()
            .name("janus-log".into())
            .spawn(move || {
                let user = user;
                IN_CALLBACK.with(|f| f.set(true));
                loop {
                    let next = {
                        let mut q = p.queue.lock().unwrap_or_else(|e| e.into_inner());
                        loop {
                            if let Some(l) = q.lines.pop_front() {
                                break Some(l);
                            }
                            if q.closed {
                                break None;
                            }
                            q = p.cv.wait(q).unwrap_or_else(|e| e.into_inner());
                        }
                    };
                    let Some((level, component, text)) = next else {
                        return;
                    };
                    let (Ok(component), Ok(text)) = (
                        CString::new(component.replace('\0', " ")),
                        CString::new(text.replace('\0', " ")),
                    ) else {
                        continue;
                    };
                    // A panic in a Rust callback must not kill the pump.
                    let _ = catch_unwind(AssertUnwindSafe(|| {
                        // SAFETY: the application's callback contract.
                        unsafe { cb(level, component.as_ptr(), text.as_ptr(), user.0) }
                    }));
                }
            })
            .expect("spawn log thread");
        *pump.thread.lock().unwrap() = Some(handle);
        pump
    }

    fn push(&self, level: c_int, component: &str, text: &str) {
        let mut q = self.queue.lock().unwrap_or_else(|e| e.into_inner());
        if q.lines.len() >= LOG_QUEUE_CAP {
            q.lines.pop_front();
            self.dropped.fetch_add(1, Ordering::Relaxed);
        }
        q.lines
            .push_back((level, component.to_owned(), text.to_owned()));
        self.cv.notify_one();
    }

    /// Deliver what is queued, then end the thread.
    fn close(&self) {
        self.queue.lock().unwrap_or_else(|e| e.into_inner()).closed = true;
        self.cv.notify_all();
        if let Some(t) = self.thread.lock().unwrap_or_else(|e| e.into_inner()).take() {
            let _ = t.join();
        }
    }
}

// ---------------------------------------------------------------- exported functions

/// Version of the C ABI (`JANUS_ABI_VERSION`). Check it against the header you built with.
#[unsafe(no_mangle)]
pub extern "C" fn janus_client_abi_version() -> c_int {
    JANUS_ABI_VERSION
}

/// Library version, a static NUL-terminated string (do not free).
#[unsafe(no_mangle)]
pub extern "C" fn janus_client_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr().cast()
}

/// Start the client inside this process. `config_json` is `{"version":1,"share":{…},"client":{…}}`
/// (both sections optional). `log` may be null. On success `*out` is the handle; release it with
/// `janus_client_stop`. One client per process: a second start fails with
/// `JANUS_E_ALREADY_STARTED` until the first is stopped.
///
/// # Safety
/// `config_json` must be a NUL-terminated string, `out` a valid pointer, and `user` usable from
/// the callback thread.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_start(
    config_json: *const c_char,
    log: janus_log_fn,
    user: *mut c_void,
    out: *mut *mut janus_client,
) -> c_int {
    ffi(|| {
        if out.is_null() {
            return Err(err(JANUS_E_INVALID_ARG, "out is null"));
        }
        // SAFETY: the caller's contract.
        unsafe { *out = std::ptr::null_mut() };
        let json = unsafe { str_arg(config_json, "config_json") }?;
        let pump = log.map(|cb| LogPump::start(cb, user));
        let sink: Option<Sink> = pump.as_ref().map(|p| {
            let p = Arc::clone(p);
            Arc::new(move |l: &Line| p.push(l.level as c_int, l.component, &l.text)) as Sink
        });
        let started =
            parse_config(json, sink, pump.is_some()).and_then(|cfg| Ok(Client::start(cfg)?));
        match started {
            Ok(client) => {
                let h = Box::new(janus_client { client, pump });
                // SAFETY: `out` was checked.
                unsafe { *out = Box::into_raw(h) };
                Ok(())
            }
            Err(e) => {
                if let Some(p) = pump {
                    p.close();
                }
                Err(e)
            }
        }
    })
}

/// How to mount the share, as JSON: `{"url":"smb://127.0.0.1:4445/backup","host":…,"port":…,
/// "share":…,"user":…,"password":…}`. The caller frees `*json_out` with `janus_free_string`.
///
/// # Safety
/// `c` must be a live handle, `json_out` a valid pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_mount_info(
    c: *mut janus_client,
    json_out: *mut *mut c_char,
) -> c_int {
    ffi(|| {
        let h = unsafe { handle(c) }?;
        let info = h.client.mount_info()?;
        let json =
            serde_json::to_string(&info).map_err(|e| err(JANUS_E_INTERNAL, e.to_string()))?;
        out_string(json_out, json)
    })
}

/// `0` when a share is configured and the receiver answers over mTLS; `JANUS_E_NOT_READY`
/// otherwise (the blocker is in `janus_last_error`).
///
/// # Safety
/// `c` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_ready(c: *mut janus_client) -> c_int {
    ffi(|| {
        let h = unsafe { handle(c) }?;
        Ok(h.client.ready()?)
    })
}

/// Apply (and persist) a share configuration: the `share` object of the start config, bare or
/// wrapped as `{"share":{…}}`.
///
/// # Safety
/// `c` must be a live handle, `share_json` a NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_configure(
    c: *mut janus_client,
    share_json: *const c_char,
) -> c_int {
    ffi(|| {
        let h = unsafe { handle(c) }?;
        let json = unsafe { str_arg(share_json, "share_json") }?;
        let value: serde_json::Value = serde_json::from_str(json)
            .map_err(|e| err(JANUS_E_INVALID_CONFIG, format!("share JSON: {e}")))?;
        let share_value = match value.get("share") {
            Some(s) => s.clone(),
            None => value,
        };
        let share: ShareConfig = serde_json::from_value(share_value)
            .map_err(|e| err(JANUS_E_INVALID_CONFIG, format!("share JSON: {e}")))?;
        Ok(h.client.configure(share)?)
    })
}

/// A status snapshot as JSON: configured, journal backlog, upload errors, pending SMB
/// operations, open handles, `log_dropped`, … Free with `janus_free_string`.
///
/// # Safety
/// `c` must be a live handle, `out` a valid pointer.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_status_json(
    c: *mut janus_client,
    out: *mut *mut c_char,
) -> c_int {
    ffi(|| {
        let h = unsafe { handle(c) }?;
        let st = h.client.status()?;
        let mut v = serde_json::to_value(st).map_err(|e| err(JANUS_E_INTERNAL, e.to_string()))?;
        let dropped = h
            .pump
            .as_ref()
            .map_or(0, |p| p.dropped.load(Ordering::Relaxed));
        v["log_dropped"] = dropped.into();
        out_string(out, v.to_string())
    })
}

/// Wait until everything written so far is on the receiver. `JANUS_E_TIMEOUT` if it is not
/// within `timeout_ms`.
///
/// # Safety
/// `c` must be a live handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_drain(c: *mut janus_client, timeout_ms: c_uint) -> c_int {
    ffi(|| {
        let h = unsafe { handle(c) }?;
        Ok(h.client.drain(Duration::from_millis(timeout_ms.into()))?)
    })
}

/// Stop the client and release the handle (also when `JANUS_E_TIMEOUT` is returned: a drain
/// that ran out of time is reported, the client is stopped anyway and the journal keeps the
/// rest for the next start). `drain_timeout_ms == 0` stops at once. Ports are free on return.
/// Refused with `JANUS_E_CALLBACK_CONTEXT` (handle still valid) when called from the log
/// callback. The handle must not be used after a stop that did not fail with that code.
///
/// # Safety
/// `c` must be a live handle that no other thread is using.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_client_stop(
    c: *mut janus_client,
    drain_timeout_ms: c_uint,
) -> c_int {
    ffi(|| {
        if c.is_null() {
            return Err(err(JANUS_E_INVALID_ARG, "client handle is null"));
        }
        if IN_CALLBACK.with(Cell::get) {
            return Err(err(
                JANUS_E_CALLBACK_CONTEXT,
                "janus_client_stop must not be called from the log callback",
            ));
        }
        // SAFETY: the caller's contract; the handle is consumed here.
        let h = unsafe { Box::from_raw(c) };
        let janus_client { client, pump } = *h;
        let mode = if drain_timeout_ms == 0 {
            StopMode::Immediate
        } else {
            StopMode::Drain(Duration::from_millis(drain_timeout_ms.into()))
        };
        let report = client.stop(mode);
        if let Some(p) = pump {
            p.close();
        }
        if report.drained {
            Ok(())
        } else {
            Err(err(
                JANUS_E_TIMEOUT,
                format!(
                    "{} bytes were not on the receiver when the client stopped",
                    report.remaining_bytes
                ),
            ))
        }
    })
}

/// Free a string returned by this library. Null is allowed.
///
/// # Safety
/// `s` must come from this library and not have been freed.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_free_string(s: *mut c_char) {
    if !s.is_null() {
        let _ = catch_unwind(|| {
            // SAFETY: allocated by CString::into_raw in this library.
            drop(unsafe { CString::from_raw(s) });
        });
    }
}

/// The message of the last failed call on this thread, copied into `buf` (NUL-terminated,
/// truncated to `cap`). Returns the full length (without the NUL), so `0` = no error and a
/// value `>= cap` means truncation.
///
/// # Safety
/// `buf` must be null or valid for `cap` bytes.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn janus_last_error(buf: *mut c_char, cap: usize) -> usize {
    catch_unwind(|| {
        LAST_ERROR.with(|e| {
            let e = e.borrow();
            let bytes = e.as_bytes();
            if !buf.is_null() && cap > 0 {
                let n = bytes.len().min(cap - 1);
                // SAFETY: `buf` is valid for `cap` bytes and n < cap.
                unsafe {
                    std::ptr::copy_nonoverlapping(bytes.as_ptr(), buf.cast::<u8>(), n);
                    *buf.add(n) = 0;
                }
            }
            bytes.len()
        })
    })
    .unwrap_or(0)
}
